import { getTableName } from 'drizzle-orm'
import { journalTables } from '../src/journal/tables'

const pgPath = 'drizzle/0076_steep_mentor.sql'
const d1Path = 'drizzle-d1/0004_certain_redwing.sql'
const marker =
  '-- Journal synchronization revision tracking. Generated by scripts/generate-journal-sync-triggers.ts.'
const tables = journalTables.map((table) => getTableName(table))
const policies = [
  'journal_sync_revisions',
  'journal_command_receipts',
  'journal_id_reservations',
]
  .map(
    (table) => `
ALTER TABLE "${table}" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "${table}" FORCE ROW LEVEL SECURITY;
CREATE POLICY journal_owner ON "${table}" TO roastbook_journal USING (owner_id = nullif(current_setting('roastbook.user_id', true), '')) WITH CHECK (owner_id = nullif(current_setting('roastbook.user_id', true), ''));
GRANT SELECT, INSERT, UPDATE, DELETE ON "${table}" TO roastbook_journal;
CREATE POLICY instance_control ON "${table}" TO CURRENT_USER USING (true) WITH CHECK (true);
`,
  )
  .join('\n--> statement-breakpoint\n')
const pg = `${marker}\n${policies}
--> statement-breakpoint
CREATE FUNCTION journal_changed() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
DECLARE journal_owner text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  IF TG_OP = 'DELETE' THEN journal_owner := OLD.owner_id; ELSE journal_owner := NEW.owner_id; END IF;
  INSERT INTO journal_sync_revisions (owner_id, value) VALUES (journal_owner, 1)
  ON CONFLICT (owner_id) DO UPDATE SET value = journal_sync_revisions.value + 1;
  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
${tables.map((table) => `--> statement-breakpoint\nCREATE TRIGGER journal_changed AFTER INSERT OR UPDATE OR DELETE ON "${table}" FOR EACH ROW EXECUTE FUNCTION journal_changed();`).join('\n')}
`
const activeOwners = [
  'journal_sync_revisions',
  'journal_command_receipts',
  'journal_id_reservations',
]
  .flatMap((table) =>
    ['insert', 'update'].map(
      (
        event,
      ) => `CREATE TRIGGER "${table}_active_owner_${event}" BEFORE ${event.toUpperCase()} ON "${table}"
WHEN NOT EXISTS (SELECT 1 FROM auth_users WHERE id = NEW.owner_id AND deleting_at IS NULL)
BEGIN SELECT RAISE(ABORT, 'Journal owner is unavailable'); END;`,
    ),
  )
  .join('\n--> statement-breakpoint\n')
const d1 = `${marker}\n${activeOwners}\n--> statement-breakpoint\n${tables
  .flatMap((table) =>
    ['insert', 'update', 'delete'].map(
      (
        event,
      ) => `CREATE TRIGGER "${table}_journal_${event}" AFTER ${event.toUpperCase()} ON "${table}"
WHEN EXISTS (SELECT 1 FROM auth_users WHERE id = ${event === 'delete' ? 'OLD' : 'NEW'}.owner_id AND deleting_at IS NULL)
BEGIN
  INSERT INTO journal_sync_revisions (owner_id, value) VALUES (${event === 'delete' ? 'OLD' : 'NEW'}.owner_id, 1)
  ON CONFLICT (owner_id) DO UPDATE SET value = value + 1;
END;`,
    ),
  )
  .join('\n--> statement-breakpoint\n')}\n`
for (const [path, generated] of [
  [pgPath, pg],
  [d1Path, d1],
]) {
  if (!path || !generated) throw new Error('Invalid trigger output')
  const current = await Bun.file(path).text()
  const base = current
    .split(marker)[0]
    ?.trimEnd()
    .replace(/--> statement-breakpoint$/, '')
    .trimEnd()
  const output = `${base}\n--> statement-breakpoint\n${generated}`
  if (process.argv.includes('--check')) {
    if (current !== output)
      throw new Error(`Journal triggers are stale: ${path}`)
  } else await Bun.write(path, output)
}
